package practice;

import java.io.Serial;
import java.io.Serializable;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * The product is licensed for 25 concurrent seats, and one SeatLicense per process counts them.
 * The license is Serializable because user sessions hold it, and the session store writes
 * sessions out and reads them back.
 */
public final class SeatLicense implements Serializable {

    @Serial
    private static final long serialVersionUID = 1L;

    public static final int SEATS = 25;

    private final AtomicInteger free = new AtomicInteger(SEATS);

    private SeatLicense() {
        checkConstruction();
    }

    private static final class Holder {
        static final SeatLicense INSTANCE = new SeatLicense();
    }

    public static SeatLicense getInstance() {
        return Holder.INSTANCE;
    }

    /** Takes a seat if one is free. */
    public boolean claim() {
        while (true) {
            int now = free.get();
            if (now == 0) return false;
            if (free.compareAndSet(now, now - 1)) return true;
        }
    }

    public void release() {
        free.incrementAndGet();
    }

    public int free() {
        return free.get();
    }

    /** Runs every time the constructor runs, whoever calls it. */
    private static void checkConstruction() {
        if (Holder.INSTANCE != null) throw new IllegalStateException("SeatLicense already exists");
    }

    /** What a session that held this license gets back when the store reads it. */
    @Serial
    private Object readResolve() {
        return Holder.INSTANCE;
    }
}

package practice;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            SeatLicense license = live();
            System.out.println("same instance: " + (license == live()));
            for (int i = 0; i < 4; i++) license.claim();
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
                out.writeObject(license);
            }
            license.claim();
            SeatLicense back;
            try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
                back = (SeatLicense) in.readObject();
            }
            System.out.println("session read back is the live license: " + (back == license));
            System.out.println("free seats seen through it: " + back.free());
            try {
                java.lang.reflect.Constructor<SeatLicense> c = SeatLicense.class.getDeclaredConstructor();
                c.setAccessible(true);
                c.newInstance();
                System.out.println("second license: built");
            } catch (java.lang.reflect.InvocationTargetException refused) {
                System.out.println("second license: refused (" + refused.getCause().getMessage() + ")");
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    /** The license, with a failure in its first construction shown as the exception it threw. */
    private static SeatLicense live() {
        try {
            return SeatLicense.getInstance();
        } catch (ExceptionInInitializerError e) {
            if (e.getCause() instanceof RuntimeException cause) throw cause;
            throw e;
        }
    }
}

